17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateEmailException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.AddressNormalizer;
47	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
48	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Maximum number of owners a single city may contain; creating an owner in a city that
67	     *  already has this many owners is rejected with 409 Conflict. */
68	    private static final int MAX_OWNERS_PER_CITY = 50;
69	
70	    /** Maximum number of owners that may be created on a single day (by registration date); creating
71	     *  an owner once this many owners already carry today's registration date is rejected with
72	     *  429 Too Many Requests. */
73	    private static final int MAX_OWNERS_PER_DAY = 100;
74	
75	    /** When more than this many owners already carry today's registration date at creation time, the
76	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
77	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
78	
79	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    private final TelephoneNormalizer telephoneNormalizer;
91	
92	    private final HouseholdNormalizer householdNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper,
100	                                 TelephoneNormalizer telephoneNormalizer,
101	                                 HouseholdNormalizer householdNormalizer,
102	                                 AddressNormalizer addressNormalizer) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	        this.telephoneNormalizer = telephoneNormalizer;
108	        this.householdNormalizer = householdNormalizer;
109	        this.addressNormalizer = addressNormalizer;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        normalizeOwnerFields(owner);
143	        // Enforce the pre-persistence policies that can reject the new owner outright.
144	        rejectDisallowedOwnerCreation(owner);
145	        // Identify any existing owners who share a household (same last name and address,
146	        // compared case-insensitively with collapsed whitespace) with the owner being created.
147	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
148	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
149	        // Reject creating an owner who shares a household with an existing owner, unless the
150	        // request explicitly opts in with 'sharesHousehold' true.
151	        if (!sharesHousehold && !householdMembers.isEmpty()) {
152	            throw new DuplicateHouseholdException(
153	                "An owner with the same last name and address already exists");
154	        }
155	        // When opting in and joining an existing household, assign the new owner and every
156	        // existing member the same stable household identifier derived from the last name and
157	        // address, so all owners of the household share one 'householdId'.
158	        if (sharesHousehold && !householdMembers.isEmpty()) {
159	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
160	            owner.setHouseholdId(householdId);
161	            for (Owner member : householdMembers) {
162	                if (!householdId.equals(member.getHouseholdId())) {
163	                    member.setHouseholdId(householdId);
164	                    this.clinicService.saveOwner(member);
165	                }
166	            }
167	        }
168	        // Record the size of this owner's household after this create, i.e. the number of owners
169	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
170	        // household counts the matched members plus itself; an owner without a shared household is a
171	        // household of one. Fixed at creation time.
172	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
173	        // Record how many existing owners already share this owner's first and last name
174	        // (compared case-insensitively) before this create, fixed at creation time.
175	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
176	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
177	        // per-city sequence equal to one more than the owners already in that city, fixed at
178	        // creation time.
179	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
180	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
181	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
182	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
183	        // Flag the create when more than 80 owners have already been created on this owner's
184	        // (adjusted business-day) registration date, fixed at creation time.
185	        owner.setBulkSignupWarning(
186	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
187	        this.clinicService.saveOwner(owner);
188	        // Emit an audit line for the successful create, carrying the owner id, customer code and
189	        // registration date so the create can be traced from the dedicated AUDIT log.
190	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
191	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
192	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
193	        headers.setLocation(UriComponentsBuilder.newInstance()
194	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
195	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    /**
199	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
200	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
201	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
202	     * the sequence of create-time rejections stays readable and a new rule is added as one more
203	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
204	     * and persistence steps. The household rule stays in {@link #addOwner} itself because it shares
205	     * the matched-member lookup with the shared household-id assignment.
206	     *
207	     * @param owner the newly mapped and normalized owner being created
208	     */
209	    private void rejectDisallowedOwnerCreation(Owner owner) {
210	        rejectWhenDailyLimitReached(owner);
211	        rejectWhenCityAtCapacity(owner);
212	        rejectWhenTelephoneInUse(owner);
213	        rejectWhenEmailInUse(owner);
214	    }
215	
216	    /**
217	     * Rejects creating an owner whose lower-cased email is already used by another owner, with
218	     * 409 Conflict.
219	     *
220	     * @param owner the owner being created
221	     */
222	    private void rejectWhenEmailInUse(Owner owner) {
223	        String normalizedEmail = owner.getEmail();
224	        if (isValueInUseByExistingOwner(Owner::getEmail, this::normalizeEmail, normalizedEmail)) {
225	            throw new DuplicateEmailException(
226	                "An owner with email " + normalizedEmail + " already exists");
227	        }
228	    }
229	
230	    /**
231	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
232	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
233	     *
234	     * @param owner the owner being created
235	     */
236	    private void rejectWhenDailyLimitReached(Owner owner) {
237	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
238	            throw new DailyOwnerLimitExceededException(
239	                "The maximum number of owners that may be created today has already been reached");
240	        }
241	    }
242	
243	    /**
244	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
245	     * or more owners, with 409 Conflict.
246	     *
247	     * @param owner the owner being created
248	     */
249	    private void rejectWhenCityAtCapacity(Owner owner) {
250	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
251	            throw new CityCapacityExceededException(
252	                "The city " + owner.getCity() + " already contains the maximum number of owners");
253	        }
254	    }
255	
256	    /**
257	     * Rejects creating an owner whose normalized telephone is already used by another owner, with
258	     * 409 Conflict.
259	     *
260	     * @param owner the owner being created
261	     */
262	    private void rejectWhenTelephoneInUse(Owner owner) {
263	        String normalizedTelephone = owner.getTelephone();
264	        if (isTelephoneInUse(normalizedTelephone)) {
265	            throw new DuplicateTelephoneException(
266	                "An owner with telephone " + normalizedTelephone + " already exists");
267	        }
268	    }
269	
270	    /**
271	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
272	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
273	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
274	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
275	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
276	     * server's current date. Canonicalising the address here, before the household checks read it,
277	     * ensures duplicate detection and the shared household id both compare the normalized form.
278	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
279	     * duplicate, household and customer-code rules.
280	     *
281	     * @param owner the newly mapped owner to canonicalize
282	     */
283	    private void normalizeOwnerFields(Owner owner) {
284	        // Normalize the address on create so it is stored and returned in canonical form and every
285	        // later comparison (household duplicate detection and the shared household id) uses it.
286	        // A value that is blank after normalization is rejected with 400.
287	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
288	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
289	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
290	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
291	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
292	        // Store the (already syntactically validated) email lower-cased so it is persisted and
293	        // returned in canonical form. A missing email is left untouched.
294	        owner.setEmail(normalizeEmail(owner.getEmail()));
295	        // Default the registration date to the server's current date when the client did not
296	        // supply one, then roll the effective date forward to a business day so a Saturday or
297	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
298	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
299	        // date-derived field (such as the membership number's year segment) and the per-day
300	        // create-limit are computed from.
301	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
302	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
303	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
304	    }
305	
306	    /**
307	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
308	     * following Monday, while a weekday is returned unchanged. Applied to the effective
309	     * registration date (whether supplied in the request or defaulted to the server date) so the
310	     * persisted registration date, every value derived from it and the per-day create-limit all
311	     * use the adjusted business day.
312	     *
313	     * @param date the effective registration date
314	     * @return the same date if it is a weekday, otherwise the following Monday
315	     */
316	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
317	        java.time.LocalDate adjusted = date;
318	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
319	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
320	            adjusted = adjusted.plusDays(1);
321	        }
322	        return adjusted;
323	    }
324	
325	    /**
326	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
327	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
328	     * syntactically valid address (rejecting anything else with 400).
329	     *
330	     * @param email the email value (may be {@code null})
331	     * @return the lower-cased email, or {@code null} if the input was {@code null}
332	     */
333	    private String normalizeEmail(String email) {
334	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
335	    }
336	
337	    /**
338	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
339	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
340	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
341	     * the owners already in that city (e.g. 'LON-SMI-0007').
342	     *
343	     * @param city     the owner's city
344	     * @param lastName the owner's last name
345	     * @return the formatted customer code
346	     */
347	    private String nextCustomerCode(String city, String lastName) {
348	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
349	            .toUpperCase(java.util.Locale.ROOT);
350	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
351	            .toUpperCase(java.util.Locale.ROOT);
352	        int sequence = countOwnersInCity(city) + 1;
353	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
354	    }
355	
356	    /**
357	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
358	     * fix the per-city sequence of an owner's customer code at creation time.
359	     *
360	     * @param city the city of the owner being created
361	     * @return the number of existing owners in a matching city
362	     */
363	    private int countOwnersInCity(String city) {
364	        return (int) this.clinicService.findAllOwners().stream()
365	            .filter(existing -> existing.getCity() != null
366	                && existing.getCity().equalsIgnoreCase(city))
367	            .count();
368	    }
369	
370	    /**
371	     * Counts the existing owners whose registration date is the given adjusted business day. Used
372	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
373	     * owners already carry that business day as their registration date.
374	     *
375	     * @param date the adjusted business-day registration date to match
376	     * @return the number of existing owners registered on that date
377	     */
378	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
379	        return (int) this.clinicService.findAllOwners().stream()
380	            .filter(existing -> date.equals(existing.getRegistrationDate()))
381	            .count();
382	    }
383	
384	    /**
385	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
386	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
387	     *
388	     * @param customerCode     the owner's customer code
389	     * @param registrationDate the owner's registration date
390	     * @return the formatted membership number
391	     */
392	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
393	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
394	    }
395	
396	    /**
397	     * Determines whether the given normalized telephone is already used by an existing owner.
398	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
399	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
400	     * as the same number.
401	     *
402	     * @param normalizedTelephone the normalized (E.164) telephone to look for
403	     * @return {@code true} if another owner already uses this telephone
404	     */
405	    private boolean isTelephoneInUse(String normalizedTelephone) {
406	        return isValueInUseByExistingOwner(Owner::getTelephone, telephoneNormalizer::normalize,
407	            normalizedTelephone);
408	    }
409	
410	    /**
411	     * Determines whether the given already-normalized value is used by an existing owner for the
412	     * field read by {@code accessor}, comparing each existing owner's value in the same normalized
413	     * form produced by {@code normalizer}. Shared by the create-time uniqueness rules so each rule
414	     * only supplies the field to read and how to normalize it.
415	     *
416	     * @param accessor        reads the field to compare from an existing owner
417	     * @param normalizer      canonicalizes an existing owner's value into the same form as
418	     *                        {@code normalizedValue}
419	     * @param normalizedValue the already-normalized value to look for
420	     * @return {@code true} if an existing owner already uses this value
421	     */
422	    private boolean isValueInUseByExistingOwner(java.util.function.Function<Owner, String> accessor,
423	                                                java.util.function.UnaryOperator<String> normalizer,
424	                                                String normalizedValue) {
425	        if (normalizedValue == null) {
426	            return false;
427	        }
428	        return this.clinicService.findAllOwners().stream()
429	            .map(accessor)
430	            .map(normalizer)
431	            .anyMatch(normalizedValue::equals);
432	    }
433	
434	    /**
435	     * Returns the existing owners who share the given household, i.e. have the same last name and
436	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
437	     * differing only in letter case or in incidental whitespace are treated as the same household.
438	     *
439	     * @param lastName the last name of the owner being created
440	     * @param address  the address of the owner being created
441	     * @return the existing owners with a matching last name and address (possibly empty)
442	     */
443	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
444	        String householdKey = householdNormalizer.householdKey(lastName, address);
445	        return this.clinicService.findAllOwners().stream()
446	            .filter(existing -> householdNormalizer
447	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
448	            .toList();
449	    }
450	
451	    /**
452	     * Counts the existing owners who share the given first and last name, compared
453	     * case-insensitively. Used to fix an owner's namesake count at creation time.
454	     *
455	     * @param firstName the first name of the owner being created
456	     * @param lastName  the last name of the owner being created
457	     * @return the number of existing owners with a matching first and last name
458	     */
459	    private int countNamesakes(String firstName, String lastName) {
460	        return (int) this.clinicService.findAllOwners().stream()
461	            .filter(existing -> existing.getFirstName() != null
462	                && existing.getFirstName().equalsIgnoreCase(firstName)
463	                && existing.getLastName() != null
464	                && existing.getLastName().equalsIgnoreCase(lastName))
465	            .count();
466	    }
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Override
470	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
471	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
472	        if (currentOwner == null) {
473	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
474	        }
475	        currentOwner.setAddress(ownerFieldsDto.getAddress());
476	        currentOwner.setCity(ownerFieldsDto.getCity());
477	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
478	        currentOwner.setLastName(ownerFieldsDto.getLastName());
479	        // Normalize the telephone to canonical E.164 form so it is stored and returned
480	        // consistently with create; an unformattable value is rejected with 400.
481	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
482	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
483	        this.clinicService.saveOwner(currentOwner);
484	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
485	    }
486	
487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Transactional
489	    @Override
490	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
491	        Owner owner = this.clinicService.findOwnerById(ownerId);
492	        if (owner == null) {
493	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	        }
495	        this.clinicService.deleteOwner(owner);
496	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
502	        Owner owner = this.clinicService.findOwnerById(ownerId);
503	        if (owner == null) {
504	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
505	        }
506	        HttpHeaders headers = new HttpHeaders();
507	        Pet pet = petMapper.toPet(petFieldsDto);
508	        owner.setId(ownerId);
509	        pet.setOwner(owner);
510	        pet.getType().setName(null);
511	        this.clinicService.savePet(pet);
512	        PetDto petDto = petMapper.toPetDto(pet);
513	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
514	            .buildAndExpand(pet.getId()).toUri());
515	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
516	    }
517	
518	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
519	    @Override
520	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
521	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
522	        if (currentOwner != null) {
523	            Pet currentPet = this.clinicService.findPetById(petId);
524	            if (currentPet != null) {
525	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
526	                currentPet.setName(petFieldsDto.getName());
527	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
528	                this.clinicService.savePet(currentPet);
529	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
530	            }
531	        }
532	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
533	    }
534	
535	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
536	    @Override
537	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
538	        HttpHeaders headers = new HttpHeaders();
539	        Visit visit = visitMapper.toVisit(visitFieldsDto);
540	        Pet pet = new Pet();
541	        pet.setId(petId);
542	        visit.setPet(pet);
543	        this.clinicService.saveVisit(visit);
544	        VisitDto visitDto = visitMapper.toVisitDto(visit);
545	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
546	            .buildAndExpand(visit.getId()).toUri());
547	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
548	    }
549	
550	
551	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
552	    @Override
553	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
554	        Owner owner = this.clinicService.findOwnerById(ownerId);
555	        if (owner != null) {
556	            Pet pet = owner.getPet(petId);
557	            if (pet != null) {
558	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
559	            }
560	        }
561	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
562	    }
563	}
